+	// transfer encoding, so the server can reject oversize up front.
+	req.ContentLength = st.Size()
+	if c.APIKey != "" {
+		req.Header.Set("Authorization", "Bearer "+c.APIKey)
+	}
+	req.Header.Set("X-Filename", filepath.Base(path))
