+		req.Header.Set("Content-Type", contentType)
+	}
+	if cliVersion != "" {
+		req.Header.Set("X-CLI-Version", cliVersion)
+	}
+	if idempotencyKey != "" {
+		req.Header.Set("Idempotency-Key", idempotencyKey)
+	}
