+// safe on the shared origin.
+const INLINE_ALLOWLIST = new Set<string>([
+  "image/png",
+  "image/jpeg",
+  "image/gif",
+  "image/webp",
+  "image/avif",
+  "video/mp4",
+  "video/webm",
+  "audio/mpeg",
+  "audio/mp4",
+  "text/plain",
+  "application/pdf",
+]);
