+    const size = row.file_size;
+    const match = rangeHeader.match(/^bytes=(\d*)-(\d*)$/);
+    if (!match || (match[1] === "" && match[2] === "")) {
+      return textResponse(416, "Range Not Satisfiable");
+    }
